#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

static const int MOD = 998244353;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

const int MAXV = 200000;
int mu[MAXV + 1];
vector<int> primes;
bool is_prime[MAXV + 1];
long long R[MAXV + 1];
long long invR[MAXV + 1];
long long f[MAXV + 1];
vector<int> divisors_list[MAXV + 1];
bool seen[MAXV + 1];

void sieve() {
    fill(is_prime + 2, is_prime + MAXV + 1, true);
    mu[1] = 1;
    for (int i = 2; i <= MAXV; i++) {
        if (is_prime[i]) {
            primes.push_back(i);
            mu[i] = -1;
        }
        for (int p : primes) {
            if (i * p > MAXV) break;
            is_prime[i * p] = false;
            if (i % p == 0) {
                mu[i * p] = 0;
                break;
            } else {
                mu[i * p] = -mu[i];
            }
        }
    }

    long long inv9 = modInverse(9);
    for (int i = 1; i <= MAXV; i++) {
        long long num = (power(10, i) - 1 + MOD) % MOD;
        R[i] = (num * inv9) % MOD;
        invR[i] = modInverse(R[i]);
        f[i] = 1;
    }

    for (int c = 1; c <= MAXV; c++) {
        for (int d = c; d <= MAXV; d += c) {
            divisors_list[d].push_back(c);
            int k = d / c;
            if (mu[k] == 1) {
                f[d] = (f[d] * R[c]) % MOD;
            } else if (mu[k] == -1) {
                f[d] = (f[d] * invR[c]) % MOD;
            }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    sieve();

    int n;
    if (!(cin >> n)) return 0;
    long long current_lcm = 1;
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        for (int d : divisors_list[a]) {
            if (!seen[d]) {
                seen[d] = true;
                current_lcm = (current_lcm * f[d]) % MOD;
            }
        }
        cout << current_lcm << "\n";
    }

    return 0;
}

