using namespace std;

int n;
long long k;
vector<vector<int>> adj;
vector<int> sz;
vector<int> depth;
vector<int> parent_node;
vector<bool> in_S;

void dfs(int u, int p, int d) {
    depth[u] = d;
    parent_node[u] = p;
    sz[u] = 1;
    for (int v : adj[u]) {
        if (v != p) {
            dfs(v, u, d + 1);
            sz[u] += sz[v];
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> n >> k)) return 0;

    adj.assign(n + 1, vector<int>());
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    sz.assign(n + 1, 0);
    depth.assign(n + 1, 0);
    parent_node.assign(n + 1, 0);
    dfs(1, 0, 0);

    long long sum_depth = 0;
    for (int i = 1; i <= n; i++) {
        sum_depth += depth[i];
    }

    long long min_val = n;
    long long max_val = n + sum_depth;

    if (k < min_val || k > max_val) {
        cout << "No\n";
        return 0;
    }

    long long rem = k - n;
    vector<int> order(n - 1);
    iota(order.begin(), order.end(), 2);
    sort(order.begin(), order.end(), [](int a, int b) {
        return sz[a] > sz[b];
    });

    in_S.assign(n + 1, false);
    for (int u : order) {
        if (sz[u] <= rem) {
            in_S[u] = true;
            rem -= sz[u];
        }
    }

    if (rem != 0) {
        cout << "No\n";
        return 0;
    }

    vector<pair<int, int>> nodes;
    nodes.reserve(n);
    nodes.push_back({0, 1});
    for (int i = 2; i <= n; i++) {
        int val = in_S[i] ? depth[i] : -depth[i];
        nodes.push_back({val, i});
    }

    sort(nodes.begin(), nodes.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    vector<int> P(n + 1);
    for (int rank = 1; rank <= n; rank++) {
        int u = nodes[rank - 1].second;
        P[u] = rank;
    }

    cout << "Yes\n";
    for (int i = 1; i <= n; i++) {
        cout << P[i] << (i == n ? "" : " ");
    }
    cout << "\n";

    return 0;
}

