    int n;
    long long k;
    if (!(cin >> n >> k)) return;

    if (n % 2 == 0 || k % 2 == 1 || k < n - 1 || k > (1LL * n * n - 1) / 2) {
        cout << "No\n";
        return;
    }

    int m = (n - 1) / 2;
    long long s = (k - (n - 1)) / 2;

    vector<int> t(m);
    for (int i = 0; i < m; i++) {
        t[i] = (s + m - 1 - i) / m;
    }

    string ans;
    ans.reserve(n * n);

    for (int v : t) {
        ans.append(2 * v, 'R');
        ans.push_back('D');
        ans.append(2 * v, 'L');
        ans.push_back('D');
    }

    for (int j = 1; j <= m; j++) {
        int cnt = 0;
        for (int v : t) {
            if (v >= j) cnt++;
        }
        int d = 2 * (m - cnt);
        ans.push_back('R');
        ans.append(d, 'U');
        ans.push_back('R');
        ans.append(d, 'D');
    }

    cout << "Yes\n";
    cout << ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t) {
        while (t--) {
            solve_test();
        }
    }
    return 0;
}

#include <iostream>
