    vector<int> diff_a(2 * n);
    vector<int> diff_b(n);

    for (int i = 0; i < n; i++) {
        diff_a[i] = a[(i + 1) % n] ^ a[i];
        diff_a[i + n] = diff_a[i];
        diff_b[i] = b[(i + 1) % n] ^ b[i];
    }

    vector<int> pi = compute_pi(diff_b);

    int j = 0;
    for (int i = 0; i < 2 * n - 1; i++) {
