using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int h, w;
    if (!(cin >> h >> w)) return 0;

    vector<string> grid(h);
    for (int i = 0; i < h; i++) {
        cin >> grid[i];
    }

    long long total_ans = 0;

    for (int j = 0; j < w - 1; j++) {
        vector<vector<int>> match_cost(h + 1, vector<int>(h + 1, 0));
        for (int i = 0; i <= h; i++) {
            for (int k = 0; k <= h; k++) {
                int cnt = 0;
                int start_r = max(0, k - i);
                int end_r = h - i;
                for (int r = start_r; r < end_r; r++) {
                    int s = r + i - k;
                    if (s >= 0 && s < h - k) {
                        if (grid[r][j] == grid[s][j + 1]) {
                            cnt++;
                        }
                    }
                }
                match_cost[i][k] = cnt;
            }
        }

        vector<vector<int>> dp(h + 1, vector<int>(h + 1, 1e9));
        dp[h][h] = 0;

        for (int i = h; i >= 0; i--) {
            for (int k = h; k >= 0; k--) {
                if (i == h && k == h) continue;
                int cur = 1e9;
                if (i + 1 <= h) {
                    cur = min(cur, dp[i + 1][k] + match_cost[i][k]);
                }
                if (k + 1 <= h) {
                    cur = min(cur, dp[i][k + 1] + match_cost[i][k]);
                }
                dp[i][k] = cur;
            }
        }

        total_ans += dp[0][0];
    }

    cout << total_ans << "\n";

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> adj(n + 1);
    vector<int> deg(n + 1, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
        deg[u]++;
        deg[v]++;
    }

    for (int i = 1; i <= n; i++) {
        if (deg[i] % 2 != 0) {
            cout << "No\n";
            return 0;
        }
    }

    int c4 = 0;
    bool has_ge6 = false;
    vector<int> deg4_nodes;

    for (int i = 1; i <= n; i++) {
        if (deg[i] >= 6) {
            has_ge6 = true;
        } else if (deg[i] == 4) {
            c4++;
            deg4_nodes.push_back(i);
        }
    }

    if (has_ge6 || c4 >= 3) {
        cout << "Yes\n";
        return 0;
    }

    if (c4 <= 1) {
        cout << "No\n";
        return 0;
    }

    int u = deg4_nodes[0];
    int v = deg4_nodes[1];

    bool loop_at_u = false;
    for (int start_nbr : adj[u]) {
        int prev = u;
        int cur = start_nbr;
        while (cur != u && cur != v) {
            int nxt = -1;
            for (int neighbor : adj[cur]) {
                if (neighbor != prev) {
                    nxt = neighbor;
                    break;
                }
            }
            prev = cur;
            cur = nxt;
        }
        if (cur == u) {
            loop_at_u = true;
            break;
        }
    }

    if (loop_at_u) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }

    return 0;
}
